const pages=['home','about','projects','heart-of-chaos'];
function resize(){document.documentElement.style.setProperty('--scale',Math.min(innerWidth/1440,innerHeight/900));}
addEventListener('resize',resize);resize();
function route(){let id=location.hash.slice(1)||'home';if(!pages.includes(id))id='home';for(const page of document.querySelectorAll('.page'))page.hidden=page.id!==id;document.title=({home:'Mars Guo',about:'About Mars Guo',projects:'Project catalogue','heart-of-chaos':'Heart of Chaos'})[id]+' · Personal Archive';}
addEventListener('hashchange',route);route();
function hit(page,label,x,y,w,h,action,img){const b=document.createElement('button');b.className='hit'+(img?' hit-img':'');b.setAttribute('aria-label',label);Object.assign(b.style,{left:x+'px',top:y+'px',width:w+'px',height:h+'px',color:'transparent',background:img?`url('assets/buttons/${img}') no-repeat center/100% 100%`:'transparent'});if(!img)b.textContent=label;b.onclick=typeof action==='string'?()=>location.hash=action:action;document.getElementById(page).append(b);}
const dialog=document.getElementById('details');function show(title,text){dialog.querySelector('h2').textContent=title;dialog.querySelector('p').textContent=text;dialog.showModal();}document.getElementById('close-dialog').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close()});
hit('home','Enter his personal Archive',447,541,546,52,'about','Enter button.png');hit('about','View Projects',818,638,265,56,'projects','View projects.png');
for(const page of pages){if(page!=='home')hit(page,'Home',1153,67,100,50,'home');hit(page,'Donate to author',1197,861,243,39,()=>show('Support the author','Thank you for your interest in supporting Mars Guo. A donation link has not been provided for this archive.'));}
hit('projects','Heart of Chaos',687,243,572,85,'heart-of-chaos','Projects 1.png');hit('projects','宋朝可怜人的友谊',680,435,572,85,()=>show('宋朝可怜人的友谊','Exploring the Poetry of Huang Tingjian. Additional project content has not been provided.'),'Projects 2.png');hit('projects','Industrial Uprising',660,628,611,85,()=>show('Industrial Uprising','A game about the development of industry. Additional project content has not been provided.'),'Projects 3.png');hit('heart-of-chaos','See more',847,627,265,56,'projects','See more.png');
['72:737','72:796','72:792','72:788','72:858'].forEach(id=>{const e=document.querySelector(`[data-node-id="${id}"]`);if(e)e.style.display='none';});['72:830','72:831'].forEach(id=>{const e=document.querySelector(`[data-node-id="${id}"]`);if(e)e.style.display='none';});
addEventListener('keydown',e=>{if(dialog.open)return;const n=pages.indexOf(location.hash.slice(1)||'home');if(e.key==='ArrowRight'&&n<3)location.hash=pages[n+1];if(e.key==='ArrowLeft'&&n>0)location.hash=pages[n-1];});
